frappe.ui.form.on('Performance Settings', {

    onload: function(frm) {
        // Auto-fill rating criteria saat dokumen baru, jalankan hanya 1 kali
        if (frm.is_new() && !frm.__criteria_auto_filled) {
            frm.clear_table('rating_criteria');

            const default_criteria = [
                { criteria_name: 'Completes tasks within the predetermined timeframe', weightage_: 20 },
                { criteria_name: 'Communicates critical information clearly with team', weightage_: 20 },
                { criteria_name: 'Proactive rather than reactive during projects',      weightage_: 20 },
                { criteria_name: 'Competencies / Behaviors',                           weightage_: 20 },
                { criteria_name: 'Teamwork & Collaboration',                           weightage_: 20 },
            ];

            default_criteria.forEach(item => {
                let row = frm.add_child('rating_criteria');
                row.criteria_name = item.criteria_name;
                frappe.model.set_value(row.doctype, row.name, 'weightage_', 20);
            });

            frm.__criteria_auto_filled = true;
            frm.refresh_field('rating_criteria');
        }
    },

    refresh: function(frm) {
        // Blast Email button
        if (!frm.is_new()) {
            frm.add_custom_button(__('Blast Email'), function() {
                frappe.confirm('Send email to all appraisees?', () => {
                    frappe.call({
                        method: "blast_email_performance",
                        args: {
                            docname: frm.doc.name
                        },
                        callback: function(r) {
                            // response ditangani oleh server script via frappe.msgprint
                        }
                    });
                });
            }, __("Actions"));
        }
    },

    get_employee: function(frm) {
        if (!frm.doc.company) {
            frappe.msgprint(__('Pilih Company terlebih dahulu.'));
            return;
        }
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Employee',
                filters: [
                    ['company', '=', frm.doc.company],
                    ['status',  '=', 'Active']
                ],
                limit_page_length: 1000,
                fields: ['name', 'employee_name', 'department', 'designation', 'branch']
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    frm.clear_table('appraisees');
                    r.message.forEach(emp => {
                        let row = frm.add_child('appraisees');
                        row.employee      = emp.name;
                        row.employee_name = emp.employee_name;
                        row.department    = emp.department;
                        row.designation   = emp.designation;
                        row.branch        = emp.branch;
                    });
                    frm.refresh_field('appraisees');
                    frappe.msgprint(__('Success.'));
                } else {
                    frappe.msgprint(__('There is no active employee in this company.'));
                }
            }
        });
    }
});

frappe.ui.form.on('Performance Evaluation', {
    refresh: function(frm) {
        manage_rating_access(frm);
        lock_weightage(frm);
    },
    onload: function(frm) {
        manage_rating_access(frm);
        lock_weightage(frm);
    }
});

// Trigger untuk Tabel Goal Progression — kunci weightage_ saat baris dibuka
frappe.ui.form.on('Goal Progression Detail', {
    form_render: function(frm, cdt, cdn) {
        lock_weightage(frm);
    }
});

// Trigger untuk Tabel Self Review (Karyawan)
frappe.ui.form.on('Self Review Detail', {
    form_render: function(frm, cdt, cdn) {
        manage_rating_access(frm);
    }
});

// Trigger untuk Tabel Manager Review (Line Manager)
frappe.ui.form.on('Manager Review Detail', {
    form_render: function(frm, cdt, cdn) {
        manage_rating_access(frm);
    }
});


// ----------------------------------------------------------------
// Kunci weightage_ di child table Goal Progression
// Berlaku untuk SEMUA user tanpa pengecualian
// ----------------------------------------------------------------
function lock_weightage(frm) {
    // Kunci di level grid (mencegah edit langsung di tabel)
    frm.fields_dict['goal_progression'].grid.update_docfield_property(
        'weightage_', 'read_only', 1
    );

    // Kunci di level dialog (mencegah edit saat baris dibuka via ikon pensil)
    setTimeout(() => {
        $('[data-fieldname="weightage_"] input').prop('disabled', true);
        $('[data-fieldname="weightage_"] input').css({
            'pointer-events': 'none',
            'background'    : 'var(--disabled-control-bg)',
            'color'         : 'var(--disabled-text-color)',
        });
    }, 300);
}


// ----------------------------------------------------------------
// Kelola akses rating berdasarkan role
// ----------------------------------------------------------------
function manage_rating_access(frm) {

    // -------------------------------------------------------------
    // KONDISI 1: EMPLOYEE (bukan Line Manager)
    // -------------------------------------------------------------
    if (frappe.user.has_role('Employee') && !frappe.user.has_role('Line Manager')) {

        frm.set_df_property('manager_review', 'read_only', 1);

        setTimeout(() => {
            $('[data-fieldname="manager_rating"] .rating').css('pointer-events', 'none');
            $('.grid-row [data-fieldname="manager_rating"]').css('pointer-events', 'none');
        }, 300);

        if (frm.doc.status !== 'Draft') {
            frm.set_df_property('self_review', 'read_only', 1);
            setTimeout(() => {
                $('[data-fieldname="self_rating"] .rating').css('pointer-events', 'none');
                $('.grid-row [data-fieldname="self_rating"]').css('pointer-events', 'none');
            }, 300);
        }
    }

    // -------------------------------------------------------------
    // KONDISI 2: LINE MANAGER
    // -------------------------------------------------------------
    if (frappe.user.has_role('Line Manager')) {

        frm.set_df_property('self_review', 'read_only', 1);

        setTimeout(() => {
            $('[data-fieldname="self_rating"] .rating').css('pointer-events', 'none');
            $('.grid-row [data-fieldname="self_rating"]').css('pointer-events', 'none');
        }, 300);

        if (frm.doc.docstatus < 2) {
            frm.set_df_property('manager_review', 'read_only', 0);
            setTimeout(() => {
                $('[data-fieldname="manager_rating"] .rating').css('pointer-events', 'auto');
                $('.grid-row [data-fieldname="manager_rating"]').css('pointer-events', 'auto');
            }, 300);
        }
    }
}

