frappe.ui.form.on('Performance Evaluation', {
    refresh: function(frm) {
        // Scores are authoritative from the server (Before Save script); only render the band here.
        render_performance_category(frm, frm.doc.final_score || 0);
    }
});

frappe.ui.form.on('Goal Progression Detail', {
    employee_progression_: function(frm) { calculate_goal_score(frm); },
    manager_adjusted_progression_: function(frm) { calculate_goal_score(frm); },
    weightage_: function(frm) { calculate_goal_score(frm); },
    goal_progression_remove: function(frm) { calculate_goal_score(frm); }
});

frappe.ui.form.on('Self Review Detail', {
    self_rating: function(frm) { calculate_self_score(frm); },
    weightage_: function(frm) { calculate_self_score(frm); },
    self_review_remove: function(frm) { calculate_self_score(frm); }
});

frappe.ui.form.on('Manager Review Detail', {
    manager_rating: function(frm) { calculate_manager_score(frm); },
    weightage_: function(frm) { calculate_manager_score(frm); },
    manager_review_remove: function(frm) { calculate_manager_score(frm); }
});

async function calculate_goal_score(frm) {
    let total = 0;
    let table_field = frm.doc.goal_progression_ ? 'goal_progression_' : 'goal_progression';
    let rows = frm.doc[table_field] || [];
    let kra_setup = null;
    if (frm.doc.kra_and_goal_setup) {
        kra_setup = await frappe.db.get_doc('KRA and Goal Setup', frm.doc.kra_and_goal_setup);
    }
    for (let row of rows) {
        let p_emp = flt(row.employee_progression_);
        let p_man = flt(row.manager_adjusted_progression_);
        let weight = flt(row.weightage_);
        if (weight === 0 && kra_setup) {
            let detail = kra_setup.kra_and_goal_detail.find(d => d.kra_name === row.kra_name);
            if (detail) weight = flt(detail.weightage_);
        }
        let actual_prog = p_man > 0 ? p_man : p_emp; // manager-adjusted wins once set, else the employee's own progression (MP-Q6)
        total += (actual_prog / 100) * (weight / 100) * 5;
    }
    frm.set_value('total_goal_score', flt(total, 2)); // never flt() a string: locale id reads '4.00' as 400 (MP-Q4)
    calculate_final_score(frm);
}

function calculate_self_score(frm) {
    let rows = frm.doc.self_review_ || frm.doc.self_review || [];
    let total_poin = 0;
    rows.forEach(row => {
        let rating = flt(row.self_rating) * 5; // star rating ERPNext: 0–1, kalikan 5
        let weight = flt(row.weightage_);
        if (weight > 0) {
            total_poin += flt((rating * weight) / 100);
        }
    });
    frm.set_value('total_self_score', flt(total_poin, 2));
    calculate_final_score(frm);
}

function calculate_manager_score(frm) {
    let rows = frm.doc.manager_review_ || frm.doc.manager_review || [];
    let total_poin = 0;
    rows.forEach(row => {
        let rating = flt(row.manager_rating) * 5; // star rating ERPNext: 0–1, kalikan 5
        let weight = flt(row.weightage_);
        if (weight > 0) {
            total_poin += flt((rating * weight) / 100);
        }
    });
    frm.set_value('total_manager_score', flt(total_poin, 2));
    calculate_final_score(frm);
}

function calculate_final_score(frm) {
    let g = flt(frm.doc.total_goal_score);
    let s = flt(frm.doc.total_self_score);
    let m = flt(frm.doc.total_manager_score);
    let final = flt((g + s + m) / 3, 2);
    frm.set_value('final_score', final);
    render_performance_category(frm, final);
}

var PERF_CATEGORIES = [
    { score: 5, label: "Outstanding",          range: "95 – 100%", min: 4.75, max: 5,    color: "#16a34a", bg: "#f0fdf4" },
    { score: 4, label: "Exceeds Expectations", range: "85 – 94%",  min: 4.0,  max: 4.74, color: "#65a30d", bg: "#f7fee7" },
    { score: 3, label: "Meets Expectations",   range: "70 – 84%",  min: 3.0,  max: 3.99, color: "#2563eb", bg: "#eff6ff" },
    { score: 2, label: "Fair",                 range: "55 – 69%",  min: 2.0,  max: 2.99, color: "#ea580c", bg: "#fff7ed" },
    { score: 1, label: "Needs Improvement",    range: "Below 55%", min: 0,    max: 1.99, color: "#dc2626", bg: "#fef2f2" }
];

function render_performance_category(frm, final_score) {
    if (!frm.fields_dict["performance_category_html"]) return;
    var val = flt(final_score);
    var active = PERF_CATEGORIES.find(c => val >= c.min && val <= c.max) || PERF_CATEGORIES[4];
    var rows = PERF_CATEGORIES.map(cat => {
        var is_active = cat.score === active.score;
        return `<tr style="background:${is_active ? cat.bg : "transparent"}">
            <td style="padding:8px 10px;text-align:center;font-weight:600;color:${cat.color};border:1px solid #e5e7eb">${cat.score}</td>
            <td style="padding:8px 10px;color:${cat.color};border:1px solid #e5e7eb">${cat.label}</td>
            <td style="padding:8px 10px;color:${cat.color};border:1px solid #e5e7eb">${cat.range}</td>
        </tr>`;
    }).join("");
    frm.fields_dict["performance_category_html"].$wrapper.html(`
        <div style="margin-top:8px;margin-bottom:20px;">
            <table style="width:50%;border-collapse:collapse;font-size:13px;border:1px solid #e5e7eb;">
                <tr style="background:#1e3a5f;color:#fff">
                    <th style="padding:8px 10px;text-align:center;width:80px;">Score</th>
                    <th style="padding:8px 10px;text-align:left;">Label</th>
                    <th style="padding:8px 10px;text-align:left;">Range</th>
                </tr>${rows}
            </table>
        </div>`);
}

