frappe.ui.form.on('Performance Evaluation', {
    kra_and_goal_setup: function(frm) {
        if (!frm.doc.kra_and_goal_setup) return;

        frappe.db.get_doc('KRA and Goal Setup', frm.doc.kra_and_goal_setup)
            .then(kra_setup => {
                // MP-Q8: fetch_from fields (company, cycle_year) are still empty here; take them from the KRA doc.
                let company = frm.doc.company || kra_setup.company;
                let cycle_year = frm.doc.cycle_year || kra_setup.cycle_year;
                frappe.db.get_value('Performance Settings',
                    {company: company, cycle_year: cycle_year},
                    ['base_year', 'rating_criteria'],
                    function(r) {
                        let base_year = r && r.base_year ? r.base_year : cycle_year;
                        let yn = cycle_year - base_year + 1;

                        // Auto-populate Goal Progression
                        frm.clear_table('goal_progression');
                        kra_setup.kra_and_goal_detail.forEach(row => {
                            let child = frm.add_child('goal_progression');
                            child.kra_name = row.kra_name;
                            child.goal_name = row.kra_name + ' Y' + yn;
                            child.goal_description = row.goal_description;
                            child.weightage_ = row.weightage_;
                        });
                        frm.refresh_field('goal_progression');

                        // Auto-populate Self Review & Manager Review
                        // Perlu ambil full doc Performance Settings karena get_value tidak return child table
                        frappe.db.get_doc('Performance Settings',
                            `${company}-${cycle_year}`
                        ).then(settings => {
                            frm.clear_table('self_review');
                            frm.clear_table('manager_review');

                            settings.rating_criteria.forEach(criteria => {
                                let self_row = frm.add_child('self_review');
                                self_row.criteria_name = criteria.criteria_name;
                                self_row.weightage_ = criteria.weightage_;

                                let mgr_row = frm.add_child('manager_review');
                                mgr_row.criteria_name = criteria.criteria_name;
                                mgr_row.weightage_ = criteria.weightage_;
                            });

                            frm.refresh_field('self_review');
                            frm.refresh_field('manager_review');

                            // Hitung ulang score setelah populate
                            calculate_goal_score(frm);
                            calculate_self_score(frm);
                            calculate_manager_score(frm);
                        }).catch(() => {
                            frappe.msgprint({
                                title: 'Warning',
                                message: 'Performance Settings not found for this company and cycle year.',
                                indicator: 'orange'
                            });
                        });
                    }
                );
            });
    }
});

frappe.ui.form.on('Performance Settings', {
    onload: function(frm) {
        // Flag agar hanya berjalan 1 kali saat dokumen baru dibuka
        if (frm.is_new() && !frm.__criteria_auto_filled) {
            
            // 1. Bersihkan tabel
            frm.clear_table('rating_criteria'); 

            // 2. Data 5 kriteria resmi
            const default_criteria = [
                { criteria_name: 'Completes tasks within the predetermined timeframe', weight: 20 },
                { criteria_name: 'Communicates critical information clearly with team', weight: 20 },
                { criteria_name: 'Proactive rather than reactive during projects', weight: 20 },
                { criteria_name: 'Competencies / Behaviors', weight: 20 },
                { criteria_name: 'Teamwork & Collaboration', weight: 20 }
            ];

            // 3. Masukkan data menggunakan frappe.model.set_value (Lebih Agresif)
            default_criteria.forEach(item => {
                let row = frm.add_child('rating_criteria');
                
                // Set nama kriteria
                row.criteria_name = item.criteria_name; 
                
                // Gunakan frappe.model.set_value untuk memaksa field 'weightage_' menerima angka 20 murni
                frappe.model.set_value(row.doctype, row.name, 'weightage_', 20);
            });

            // Kunci flag
            frm.__criteria_auto_filled = true;

            // 4. Refresh field tabel agar perubahan ter-render di browser
            frm.refresh_field('rating_criteria');
        }
    }
});

frappe.ui.form.on('KRA and Goal Setup', {
    onload: function(frm) {
        // MP-Q3: a new KRA defaults to the logged-in user's own Employee record.
        if (!frm.is_new() || frm.doc.employee) return;
        frappe.db.get_value('Employee', {user_id: frappe.session.user, status: 'Active'}, 'name').then(r => {
            if (r && r.message && r.message.name) frm.set_value('employee', r.message.name);
        });
    }
});

// MP-Q2: ERPNext's global Employee link formatter labels every Employee link on a form with the form's
// own employee_name, so "Reports To" showed the employee's name instead of the manager's. Stricter version.
frappe.form.link_formatters['Employee'] = function (value, doc, df) {
    if (!doc || !value) return value;
    if (doc.employee === value && doc.employee_name && doc.employee_name !== value) return value + ': ' + doc.employee_name;
    if (df && df.fieldname === 'reports_to' && doc.line_manager_name) return value + ': ' + doc.line_manager_name;
    return value;
};

